-- The agent's system prompt is now entirely its own `instructions` (written by hand or generated by AI in Admin → AI Agents);
-- the locked core and the tool playbooks that used to be appended in code are gone.
--
-- prompt_tools_signature: the tools/scopes the prompt was generated for, so the form can say "tools changed since the prompt was
-- generated". NULL = hand-written (no warning).
ALTER TABLE ai_agents ADD COLUMN IF NOT EXISTS prompt_tools_signature text;

-- legacy_prompt: agents that existed before this migration relied on the code core. The next seed run appends the default rules
-- (prompts/fashion-tomodev-agent-default.md) to their instructions once and clears the flag, so their behaviour does not change.
-- New agents start with false; on a fresh database this UPDATE touches no rows.
ALTER TABLE ai_agents ADD COLUMN IF NOT EXISTS legacy_prompt boolean NOT NULL DEFAULT false;
UPDATE ai_agents SET legacy_prompt = true;
